mapper.select:
select ti.id track_id, ti.track_title, ti.cover_url, ti.media_duration, max(if(stat.stat_type = '0701', stat_num, 0)) playStatNum, max(if(stat.stat_type = '0702', stat_num, 0)) collectStatNum, max(if(stat.stat_type = '0703', stat_num, 0)) praiseStatNum, max(if(stat.stat_type = '0704', stat_num, 0)) commentStatNum from track_info ti inner join track_stat stat on stat.track_id = ti.id and stat.is_deleted = 0
and ti.user_id = #{vo.userId}
and ti.status = #{vo.status}
and ti.track_title like CONCAT('%', #{vo.trackTitle}, '%')
and ti.is_deleted = 0 group by ti.id order by ti.create_time desc
